using AcademyDesk.Api.Data; using AcademyDesk.Api.Domain.Entities; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/practice-logs")]
public sealed class PracticeLogsController(AcademyDeskDbContext db) : ControllerBase { [HttpGet] public async Task<ActionResult<IReadOnlyList<PracticeLog>>> List(Guid academyId,CancellationToken t)=>Ok(await db.PracticeLogs.AsNoTracking().Where(x=>x.AcademyId==academyId).OrderByDescending(x=>x.PracticeDate).ToListAsync(t)); [HttpPost] public async Task<ActionResult<PracticeLog>> Create(Guid academyId,PracticeLog x,CancellationToken t){if(x.MinutesPracticed<1)return BadRequest(new{message="Minutes must be greater than zero."});x.Id=Guid.NewGuid();x.AcademyId=academyId;db.PracticeLogs.Add(x);await db.SaveChangesAsync(t);return Ok(x);} [HttpPatch("{id:guid}/review")] public async Task<ActionResult<PracticeLog>> Review(Guid academyId,Guid id,ReviewPracticeLogRequest r,CancellationToken t){var x=await db.PracticeLogs.SingleOrDefaultAsync(x=>x.Id==id&&x.AcademyId==academyId,t);if(x is null)return NotFound();x.TeacherFeedback=r.TeacherFeedback?.Trim();x.Status="Reviewed";x.ReviewedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(t);return Ok(x);} }
public sealed record ReviewPracticeLogRequest(string? TeacherFeedback);
